#[cfg(test)]
mod tests {
    use std::{collections::HashSet, fs, path::Path};

    use super::*;

    #[test]
    fn zombie_nautilus_variant_catalog_is_complete_ordered_and_unique() {
        assert_eq!(VANILLA_ZOMBIE_NAUTILUS_VARIANTS.len(), 2);
        let resources: HashSet<_> = VANILLA_ZOMBIE_NAUTILUS_VARIANTS
            .iter()
            .map(|entry| entry.resource_id)
            .collect();
        assert_eq!(resources.len(), VANILLA_ZOMBIE_NAUTILUS_VARIANTS.len());
        let textures: HashSet<_> = VANILLA_ZOMBIE_NAUTILUS_VARIANT_TEXTURE_REFS
            .iter()
            .map(|texture| texture.path)
            .collect();
        assert_eq!(
            textures.len(),
            VANILLA_ZOMBIE_NAUTILUS_VARIANT_TEXTURE_REFS.len()
        );
        assert_eq!(
            ZombieNautilusModelVariant::for_vanilla_registry_id(0),
            Some(ZombieNautilusModelVariant::Temperate)
        );
        assert_eq!(
            ZombieNautilusModelVariant::for_vanilla_registry_id(1),
            Some(ZombieNautilusModelVariant::Warm)
        );
        assert_eq!(
            ZombieNautilusModelVariant::for_vanilla_registry_id(-1),
            None
        );
        assert_eq!(ZombieNautilusModelVariant::for_vanilla_registry_id(2), None);
        assert_eq!(
            ZombieNautilusModelVariant::for_resource_id("minecraft:warm"),
            Some(ZombieNautilusModelVariant::Warm)
        );
        assert_eq!(
            ZombieNautilusModelVariant::for_resource_id("minecraft:cold"),
            None
        );
        assert_eq!(
            ZombieNautilusModelVariant::Temperate.resource_id(),
            "minecraft:temperate"
        );
        assert_eq!(
            ZombieNautilusModelVariant::Temperate.builtin_model_type(),
            ZombieNautilusVariantModelType::Normal
        );
        assert_eq!(
            ZombieNautilusModelVariant::Temperate.builtin_model_key(),
            "zombie_nautilus"
        );
        assert_eq!(
            ZombieNautilusModelVariant::Temperate.builtin_texture_ref(),
            EntityModelTextureRef {
                path: "textures/entity/nautilus/zombie_nautilus.png",
                size: [128, 128]
            }
        );
        assert_eq!(
            ZombieNautilusModelVariant::Warm.builtin_model_type(),
            ZombieNautilusVariantModelType::Warm
        );
        assert_eq!(
            ZombieNautilusModelVariant::Warm.builtin_model_key(),
            "zombie_nautilus_coral"
        );
        assert_eq!(
            ZombieNautilusModelVariant::Warm.builtin_texture_ref(),
            EntityModelTextureRef {
                path: "textures/entity/nautilus/zombie_nautilus_coral.png",
                size: [128, 128]
            }
        );
    }

    #[test]
    fn production_sources_do_not_redeclare_zombie_nautilus_variant_catalog_facts() {
        let native = include_str!("../../../bbb-native/src/entity_assets.rs");
        let fixture = native
            .split("fn loads_vanilla_entity_textures_from_resource_stack")
            .nth(1)
            .and_then(|source| source.split("    #[test]").next())
            .expect("native entity texture loader fixture");
        assert_eq!(fixture.matches("entity_model_texture_refs()").count(), 3);
        for texture in VANILLA_ZOMBIE_NAUTILUS_VARIANT_TEXTURE_REFS {
            assert!(
                !fixture.contains(texture.path),
                "native fixture restored zombie-nautilus asset literal {}",
                texture.path
            );
        }
        fn visit(directory: &Path, violations: &mut Vec<String>) {
            for entry in fs::read_dir(directory).unwrap() {
                let path = entry.unwrap().path();
                if path.is_dir() {
                    visit(&path, violations);
                    continue;
                }
                if path.extension().and_then(|value| value.to_str()) != Some("rs") {
                    continue;
                }
                let display = path.to_string_lossy();
                if display.ends_with("/zombie_nautilus_variants.rs")
                    || display.ends_with("/bootstrap_catalog.rs")
                    || display.ends_with("/tests.rs")
                    || display.contains("/tests/")
                {
                    continue;
                }
                let source = fs::read_to_string(&path).unwrap();
                let production = source.split("#[cfg(test)]").next().unwrap_or(&source);
                if production.contains("enum ZombieNautilusModelVariant")
                    || production.contains("fn zombie_nautilus_variant_from_entry_id(")
                    || production.contains("fn zombie_nautilus_variant_from_vanilla_registry_id(")
                    || production.contains("fn zombie_nautilus_variant_is_coral(")
                    || production.contains("textures/entity/nautilus/zombie_nautilus.png")
                    || production.contains("matches!(variant, ZombieNautilusModelVariant::Warm)")
                    || production.contains("ZombieNautilusModelVariant::Warm =>")
                    || production.contains("variant: ZombieNautilusModelVariant::Temperate,")
                {
                    violations.push(display.to_string());
                }
            }
        }
        let mut violations = Vec::new();
        visit(
            Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap(),
            &mut violations,
        );
        assert!(
            violations.is_empty(),
            "parallel zombie-nautilus variant catalog owners: {violations:?}"
        );
    }
}
